// Remap (u0, u1) from [0,1] to [-1,1]
Float sx = 2 * u[0] - 1;
Float sy = 2 * u[1] - 1;

// Handle degeneracy at the origin
if (sx == 0 && sy == 0)
    return Point2f(0, 0);

// Determine which region of the square the sample lies in
Float r, theta;
if (std::abs(sx) > std::abs(sy)) {
    r = sx;
    theta = PiOver4 * (sy / sx);
} else {
    r = sy;
    theta = PiOver2 - PiOver4 * (sx / sy);
}

// Transform from polar coordinates to Cartesian
return Point2f(r * std::cos(theta), r * std::sin(theta));

